begin;
create temporary table refine_test(k text primary key,v uuid);grant all on refine_test to authenticated;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.denied(s text) returns void language plpgsql as $$begin begin execute s;exception when insufficient_privilege or check_violation or unique_violation or raise_exception then return;end;raise exception 'FAIL: unexpectedly allowed';end$$;
insert into refine_test select k,gen_random_uuid() from unnest(array['admin','editor','viewer','outsider']) k;
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data) select v,'authenticated','authenticated',v||'@example.test',now(),'{}' from refine_test;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='admin'),true);
insert into refine_test values('school',public.create_school('학사 개선 검증','서울','고등학교'));
insert into refine_test values('year',public.save_academic_year((select v from refine_test where k='school'),2026,0,'[{"start_date":"2026-03-01","end_date":"2026-07-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]',array[2,1,1]));
reset role;
insert into public.workspace_members(workspace_id,user_id,role) select (select v from refine_test where k='school'),v,k from refine_test where k in('editor','viewer');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='editor'),true);
select pg_temp.denied(format('select public.save_semesters(%L,%L,1,%L)',(select v from refine_test where k='school'),(select v from refine_test where k='year'),'[{"start_date":"2026-03-01","end_date":"2026-07-20"},{"start_date":"2026-08-24","end_date":"2027-02-28"}]'));
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='admin'),true);
select pg_temp.ok(public.save_semesters((select v from refine_test where k='school'),(select v from refine_test where k='year'),1,'[{"start_date":"2026-03-01","end_date":"2026-07-20"},{"start_date":"2026-08-24","end_date":"2027-02-28"}]')=2,'admin edits semesters');
select pg_temp.ok((select count(*)=4 from public.classes where academic_year_id=(select v from refine_test where k='year')),'classes unchanged');
select pg_temp.denied(format('select public.save_semesters(%L,%L,1,%L)',(select v from refine_test where k='school'),(select v from refine_test where k='year'),'[{"start_date":"2026-03-01","end_date":"2026-07-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]'));
select pg_temp.denied(format('select public.save_semesters(%L,%L,2,%L)',(select v from refine_test where k='school'),(select v from refine_test where k='year'),'[{"start_date":"2026-03-01","end_date":"2026-09-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]'));
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='editor'),true);
insert into refine_test values('plan',public.create_curriculum_draft((select v from refine_test where k='school'),2026,'[{"name":"국어","values":[2,2,1,1,1,1]}]','credits','총론 검증'));
select pg_temp.ok((select sum(hours)=8 from public.curriculum_hours where plan_id=(select v from refine_test where k='plan')),'draft values stored');
select pg_temp.ok((select unit='credits' from public.curriculum_plans where id=(select v from refine_test where k='plan')),'credits preserved');
select pg_temp.denied(format('select public.create_curriculum_draft(%L,2026,%L,%L,%L)',(select v from refine_test where k='school'),'[{"name":"국어","values":[0,0,0,0,0,0]}]','credits','overwrite'));
select pg_temp.denied(format('select public.create_curriculum_draft(%L,2027,%L,%L,%L)',(select v from refine_test where k='school'),'[{"name":"잘못된 과목","values":[1,1]}]','credits','invalid'));
select pg_temp.ok(not exists(select 1 from public.curriculum_plans where workspace_id=(select v from refine_test where k='school') and cohort_year=2027),'invalid draft rolled back');
select pg_temp.ok(not exists(select 1 from public.subjects where workspace_id=(select v from refine_test where k='school') and name='[초안] 잘못된 과목'),'no partial subjects');
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='admin'),true);
insert into public.events(workspace_id,academic_year_id,title,start_date,end_date,event_type,target_grades,activity_area) values((select v from refine_test where k='school'),(select v from refine_test where k='year'),'영역 검증','2026-11-09','2026-11-09','school','{1,2,3}','진로');
select pg_temp.ok(public.save_annual_plan((select v from refine_test where k='school'),(select v from refine_test where k='year'),0,'{"vacations":[],"days":{},"holidays":{},"timetable":[],"recurring":[],"allocations":[],"departments":["교무"],"business":[{"id":"duty","date":"2026-11-09","department":"교무","kind":"당직","text":"가상 테스트","time":"17:00","location":"교무실","participants":"담당자"}],"workSettings":{"dutyEnabled":false},"weather":{"nx":60,"ny":127,"landCode":"11B00000","tempCode":"11B10101"}}')=1,'optional work metadata and duty flag saved');
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='viewer'),true);
select pg_temp.denied(format('select public.create_curriculum_draft(%L,2027,%L,%L,%L)',(select v from refine_test where k='school'),'[{"name":"국어","values":[2,2,1,1,1,1]}]','credits','viewer'));
select pg_temp.denied(format('select public.save_semesters(%L,%L,2,%L)',(select v from refine_test where k='school'),(select v from refine_test where k='year'),'[]'));
select set_config('request.jwt.claim.sub',(select v::text from refine_test where k='outsider'),true);
select pg_temp.denied(format('select public.create_curriculum_draft(%L,2027,%L,%L,%L)',(select v from refine_test where k='school'),'[{"name":"국어","values":[2,2,1,1,1,1]}]','credits','outsider'));
select pg_temp.denied(format('select public.save_semesters(%L,%L,2,%L)',(select v from refine_test where k='school'),(select v from refine_test where k='year'),'[]'));
rollback;
select 'Semester version/scope, editor access, class preservation, atomic drafts, activity area and optional duty metadata passed; rolled back' as result;
